def extract(root="vNext15"):
    os.makedirs(root,exist_ok=True)
    for rel,b in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p) or root,exist_ok=True); open(p,"wb").write(base64.b64decode(b))
    open(os.path.join(root,"regression.py"),"wb").write(REGRESSION.encode("utf-8"))
    return root
def verify(root="vNext15"):
    fail=[]
    for f,h in ALL_HASHES.items():
        p=os.path.join(root,f)
        if not os.path.exists(p): fail.append("MISSING "+f)
        elif hashlib.sha256(open(p,"rb").read()).hexdigest()!=h: fail.append("TAMPERED "+f)
    if hashlib.sha256(open(os.path.join(root,"regression.py"),"rb").read()).hexdigest()!=REG_HASH: fail.append("regression.py TAMPERED")
    allowed=set(ALL_HASHES)|{"regression.py"}
    for f in os.listdir(root):
        if (f.endswith(".py") or f.endswith(".json")) and f not in allowed and not f.startswith("_"): fail.append("UNEXPECTED "+f)
    import json as _j
    gs=_j.load(open(os.path.join(root,"guard_set_authority.json")))
    if len(gs["authority_guards"])+len(gs["authority_controls"])!=GUARD_COUNT: fail.append("GUARD COUNT")
    if fail:
        print(">>> INTEGRITY FAILED:"); [print("  -",x) for x in fail]; return 2
    print("integrity OK (all bytes incl. completion plane verified)")
    r=subprocess.run([sys.executable,"regression.py"],cwd=root,capture_output=True,text=True); print(r.stdout,end="")
    if r.returncode or ">>> vNext15 REGRESSION PASS" not in r.stdout: print(r.stderr[-400:]); return 3
    print(">>> vNext15 RELEASE VERIFIED (behavior byte-identical + completion plane additive)"); return 0
def main():
    if "--verify-only" in sys.argv: sys.exit(verify())
    if "--verify" in sys.argv: extract(); sys.exit(verify())
    extract(); print("Extracted. Verify: python install_vNext15.py --verify")
if __name__=="__main__": main()
